//! Recreates `sign` in `wasm/src/lib.rs`.
//!
//! The page submits whatever was typed. This test submits `asdf`, draws keys
//! from `ChaCha8Rng` seeded with 123, signs with the hedged variant and an
//! empty context, then checks that verify succeeds. The hex values are that run
//! on SLH-DSA-SHA2-128s, the parameter set the demo builds.

#![cfg(feature = "slh_dsa_sha2_128s")]

use fips205::slh_dsa_sha2_128s;
use fips205::traits::{SerDes, Signer, Verifier};
use rand_chacha::rand_core::SeedableRng;

#[test]
fn wasm_sign_demo() {
    // Same steps as `wasm/src/lib.rs`.
    let message = "asdf";
    let seed = 123;
    let mut rng = rand_chacha::ChaCha8Rng::seed_from_u64(seed);
    let hedged = true;

    let (pk, sk) = slh_dsa_sha2_128s::try_keygen_with_rng(&mut rng).expect("keygen failed");
    let sig = sk.try_sign_with_rng(&mut rng, message.as_ref(), &[], hedged).expect("sign failed");
    assert!(pk.verify(message.as_ref(), &sig, &[]), "verify failed");

    assert_eq!(hex::encode(sk.into_bytes()), SK_HEX, "sk not correct");
    assert_eq!(hex::encode(sig), SIG_HEX, "sig not correct");
    assert_eq!(hex::encode(pk.into_bytes()), PK_HEX, "pk not correct");
}

const SK_HEX: &str = "932b30e756257dda01d47dd4a1b0e62abb8fa01f222ad8554ed821a89f82cbbb3f537f509949e758624a70946a776986f5af065e5e8ec3f7636b194b9c0a58f3";
const SIG_HEX: &str = "";
const PK_HEX: &str = "3f537f509949e758624a70946a776986f5af065e5e8ec3f7636b194b9c0a58f3";
